class ParticleIntrinsic {
  constructor(public color: string, public textureId: number) {}
}

class ParticleFactory {
  private cache = new Map<string, ParticleIntrinsic>();
  get(color: string, textureId: number) {
    const key = color + ':' + textureId;
    if (!this.cache.has(key)) this.cache.set(key, new ParticleIntrinsic(color, textureId));
    return this.cache.get(key)!;
  }
}

// Many Particle instances reuse the same intrinsic object from the factory

class Style {
  constructor(public color: string, public size: number) {}
}

class StyleFactory {
  private cache = new Map<string, Style>();
  get(key: string, color: string, size: number) {
    if (!this.cache.has(key)) this.cache.set(key, new Style(color, size));
    return this.cache.get(key)!;
  }
}

// Widget modifies style after getting it from the factory
const style = styleFactory.get('btn', 'blue', 12);
style.color = 'red';

