class MarkerIntrinsic { constructor(public iconId: number, public color: string) {} }
class MarkerFactory { private pool = new Map<string, MarkerIntrinsic>();
  get(iconId: number, color: string) { const key = iconId + ':' + color; if (!this.pool.has(key)) this.pool.set(key, new MarkerIntrinsic(iconId, color)); return this.pool.get(key)!; }
}
// Each marker holds extrinsic x/y and a reference to shared intrinsic from factory

